/* ════════════════════════════════════════════════════════════════════════
   pdfgen.js — minimalni izdelovalec PDF (brez zunanjih knjižnic, CSP 'self').
   Vgnezden podnabor pisave DejaVu Sans (slovenski znaki + €) za pravi izpis.
   API: var d=new PDFDoc(); d.addPage(); d.text(...); d.line(...); d.rect(...);
        d.image(jpegBytes,w,h,...); d.save('ime.pdf');
   ════════════════════════════════════════════════════════════════════════ */
(function () {
  var FONT_B64 = '';
  function b64ToBytes(b64) {
    var bin = atob(b64), n = bin.length, out = new Uint8Array(n);
    for (var i = 0; i < n; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  // ── Preprost razčlenjevalnik TTF (head, maxp, hhea, hmtx, cmap format 4) ──
  function TTF(bytes) {
    var dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    this.dv = dv; this.bytes = bytes;
    var numTables = dv.getUint16(4), off = 12, tab = {};
    for (var i = 0; i < numTables; i++) {
      var tag = String.fromCharCode(bytes[off], bytes[off + 1], bytes[off + 2], bytes[off + 3]);
      tab[tag] = { off: dv.getUint32(off + 8), len: dv.getUint32(off + 12) };
      off += 16;
    }
    this.tab = tab;
    var head = tab.head.off;
    this.unitsPerEm = dv.getUint16(head + 18);
    this.xMin = dv.getInt16(head + 36); this.yMin = dv.getInt16(head + 38);
    this.xMax = dv.getInt16(head + 40); this.yMax = dv.getInt16(head + 42);
    this.numGlyphs = dv.getUint16(tab.maxp.off + 4);
    this.numH = dv.getUint16(tab.hhea.off + 34);
    this.ascent = dv.getInt16(tab.hhea.off + 4); this.descent = dv.getInt16(tab.hhea.off + 6);
    this._parseCmap();
    this._adv = new Array(this.numGlyphs);
    var hm = tab.hmtx.off, last = 0;
    for (var g = 0; g < this.numGlyphs; g++) {
      if (g < this.numH) { last = dv.getUint16(hm + g * 4); }
      this._adv[g] = last;
    }
  }
  TTF.prototype._parseCmap = function () {
    var dv = this.dv, base = this.tab.cmap.off, nt = dv.getUint16(base + 2), sub = -1;
    for (var i = 0; i < nt; i++) {
      var pid = dv.getUint16(base + 4 + i * 8), eid = dv.getUint16(base + 6 + i * 8), o = dv.getUint32(base + 8 + i * 8);
      if ((pid === 3 && (eid === 1 || eid === 0)) || pid === 0) { sub = base + o; if (pid === 3 && eid === 1) break; }
    }
    var s = sub, fmt = dv.getUint16(s);
    this._cmap = {};
    if (fmt !== 4) return;
    var segX2 = dv.getUint16(s + 6), segCount = segX2 / 2;
    var endO = s + 14, startO = endO + segX2 + 2, deltaO = startO + segX2, rangeO = deltaO + segX2;
    for (var j = 0; j < segCount; j++) {
      var end = dv.getUint16(endO + j * 2), start = dv.getUint16(startO + j * 2);
      var delta = dv.getUint16(deltaO + j * 2), ro = dv.getUint16(rangeO + j * 2);
      for (var c = start; c <= end && c !== 0xFFFF; c++) {
        var gid;
        if (ro === 0) { gid = (c + delta) & 0xFFFF; }
        else {
          var gi = rangeO + j * 2 + ro + (c - start) * 2;
          gid = dv.getUint16(gi); if (gid !== 0) gid = (gid + delta) & 0xFFFF;
        }
        if (gid) this._cmap[c] = gid;
      }
    }
  };
  TTF.prototype.gid = function (cp) { return this._cmap[cp] || 0; };
  TTF.prototype.adv1000 = function (gid) { return Math.round(this._adv[gid] * 1000 / this.unitsPerEm); };

  var FONT = new TTF(b64ToBytes(FONT_B64));

  // ── PDF dokument ──────────────────────────────────────────────────────
  function PDFDoc(opt) {
    opt = opt || {};
    this.W = opt.width || 595.28; this.H = opt.height || 841.89;   // A4 v točkah
    this.pages = []; this.cur = null;
    this.images = [];   // {bytes,w,h}
    this._seenGid = {};
  }
  PDFDoc.prototype.addPage = function () { this.cur = { ops: [] }; this.pages.push(this.cur); return this; };
  PDFDoc.prototype._enc = function (str) {
    var out = '', s = String(str == null ? '' : str);
    for (var i = 0; i < s.length; i++) {
      var cp = s.charCodeAt(i);
      // združi surogate (izven BMP) — redko; drugače uporabi znak
      if (cp >= 0xD800 && cp <= 0xDBFF && i + 1 < s.length) { var lo = s.charCodeAt(i + 1); cp = ((cp - 0xD800) * 0x400) + (lo - 0xDC00) + 0x10000; i++; }
      var g = FONT.gid(cp); if (!g) g = FONT.gid(0x20);
      this._seenGid[g] = 1;
      out += ('000' + g.toString(16)).slice(-4);
    }
    return out;
  };
  PDFDoc.prototype.width = function (str, size) {
    var s = String(str == null ? '' : str), w = 0;
    for (var i = 0; i < s.length; i++) {
      var cp = s.charCodeAt(i);
      if (cp >= 0xD800 && cp <= 0xDBFF && i + 1 < s.length) { var lo = s.charCodeAt(i + 1); cp = ((cp - 0xD800) * 0x400) + (lo - 0xDC00) + 0x10000; i++; }
      w += FONT.adv1000(FONT.gid(cp) || FONT.gid(0x20));
    }
    return w * size / 1000;
  };
  function fmt(n) { return (Math.round(n * 100) / 100).toString(); }
  PDFDoc.prototype.text = function (x, yTop, str, o) {
    o = o || {}; var size = o.size || 10, col = o.color || [0.09, 0.13, 0.17];
    var w = this.width(str, size);
    if (o.align === 'right') x -= w; else if (o.align === 'center') x -= w / 2;
    var y = this.H - yTop;   // yTop = odmik osnovne črte od vrha
    var t = 'BT /F1 ' + fmt(size) + ' Tf ' + fmt(col[0]) + ' ' + fmt(col[1]) + ' ' + fmt(col[2]) + ' rg ';
    if (o.bold) { t += '2 Tr ' + fmt(size * 0.028) + ' w ' + fmt(col[0]) + ' ' + fmt(col[1]) + ' ' + fmt(col[2]) + ' RG '; }
    t += '1 0 0 1 ' + fmt(x) + ' ' + fmt(y) + ' Tm <' + this._enc(str) + '> Tj ';
    if (o.bold) t += '0 Tr ';
    t += 'ET';
    this.cur.ops.push(t);
    return w;
  };
  PDFDoc.prototype.line = function (x1, y1, x2, y2, o) {
    o = o || {}; var c = o.color || [0.85, 0.9, 0.88];
    this.cur.ops.push(fmt(c[0]) + ' ' + fmt(c[1]) + ' ' + fmt(c[2]) + ' RG ' + fmt(o.width || 0.7) + ' w ' +
      fmt(x1) + ' ' + fmt(this.H - y1) + ' m ' + fmt(x2) + ' ' + fmt(this.H - y2) + ' l S');
  };
  PDFDoc.prototype.rect = function (x, yTop, w, h, o) {
    o = o || {}; var y = this.H - (yTop + h), s = '';
    if (o.fill) { s += fmt(o.fill[0]) + ' ' + fmt(o.fill[1]) + ' ' + fmt(o.fill[2]) + ' rg '; }
    if (o.stroke) { s += fmt(o.stroke[0]) + ' ' + fmt(o.stroke[1]) + ' ' + fmt(o.stroke[2]) + ' RG ' + fmt(o.width || 0.7) + ' w '; }
    s += fmt(x) + ' ' + fmt(y) + ' ' + fmt(w) + ' ' + fmt(h) + ' re ' + (o.fill && o.stroke ? 'B' : o.fill ? 'f' : 'S');
    this.cur.ops.push(s);
  };
  // jpegBytes: Uint8Array (JPEG); w,h v točkah; xTop,yTop odmik od vrha levo
  PDFDoc.prototype.image = function (jpegBytes, x, yTop, w, h, iw, ih) {
    var idx = this.images.length; this.images.push({ bytes: jpegBytes, w: iw, h: ih });
    var y = this.H - (yTop + h);
    this.cur.ops.push('q ' + fmt(w) + ' 0 0 ' + fmt(h) + ' ' + fmt(x) + ' ' + fmt(y) + ' cm /Im' + idx + ' Do Q');
  };
  // ── izpis PDF v bajte ──
  function bytesFromLatin1(str) { var n = str.length, a = new Uint8Array(n); for (var i = 0; i < n; i++) a[i] = str.charCodeAt(i) & 0xFF; return a; }
  PDFDoc.prototype.build = function () {
    var chunks = [], offsets = [], pos = 0, self = this;
    function push(x) { var b = (x instanceof Uint8Array) ? x : bytesFromLatin1(x); chunks.push(b); pos += b.length; }
    var objs = [];   // vsak: function or string producing body; zbrano spodaj
    // Rezervramo številke objektov
    var oCatalog = 1, oPages = 2, oFont = 3, oCID = 4, oFD = 5, oFontFile = 6;
    var oFirstImg = 7, nImg = this.images.length;
    var oFirstPage = oFirstImg + nImg;         // page obj
    var oFirstContent = oFirstPage + this.pages.length;
    var total = oFirstContent + this.pages.length - 1;
    var body = {};
    // W (širine) za vse glife
    var W = '[0 ['; for (var g = 0; g < FONT.numGlyphs; g++) { W += FONT.adv1000(g) + (g < FONT.numGlyphs - 1 ? ' ' : ''); } W += ']]';
    var upm = FONT.unitsPerEm, sc = 1000 / upm;
    var bbox = [Math.round(FONT.xMin * sc), Math.round(FONT.yMin * sc), Math.round(FONT.xMax * sc), Math.round(FONT.yMax * sc)];
    body[oCatalog] = '<< /Type /Catalog /Pages ' + oPages + ' 0 R >>';
    var kids = ''; for (var p = 0; p < this.pages.length; p++) kids += (oFirstPage + p) + ' 0 R ';
    body[oPages] = '<< /Type /Pages /Count ' + this.pages.length + ' /Kids [' + kids + '] >>';
    body[oFont] = '<< /Type /Font /Subtype /Type0 /BaseFont /SCFont /Encoding /Identity-H /DescendantFonts [' + oCID + ' 0 R] >>';
    body[oCID] = '<< /Type /Font /Subtype /CIDFontType2 /BaseFont /SCFont /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor ' + oFD + ' 0 R /CIDToGIDMap /Identity /DW ' + FONT.adv1000(FONT.gid(0x20)) + ' /W ' + W + ' >>';
    body[oFD] = '<< /Type /FontDescriptor /FontName /SCFont /Flags 4 /FontBBox [' + bbox.join(' ') + '] /ItalicAngle 0 /Ascent ' + Math.round(FONT.ascent * sc) + ' /Descent ' + Math.round(FONT.descent * sc) + ' /CapHeight ' + Math.round(FONT.ascent * sc) + ' /StemV 88 /FontFile2 ' + oFontFile + ' 0 R >>';
    // objekti se zapišejo spodaj v vrstnem redu 1..total
    function writeObj(num, headStr, streamBytes) {
      offsets[num] = pos;
      push(num + ' 0 obj\n' + headStr);
      if (streamBytes != null) { push('\nstream\n'); push(streamBytes); push('\nendstream'); }
      push('\nendobj\n');
    }
    // Header
    push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
    writeObj(oCatalog, body[oCatalog]);
    writeObj(oPages, body[oPages]);
    writeObj(oFont, body[oFont]);
    writeObj(oCID, body[oCID]);
    writeObj(oFD, body[oFD]);
    // FontFile2
    writeObj(oFontFile, '<< /Length ' + FONT.bytes.length + ' /Length1 ' + FONT.bytes.length + ' >>', FONT.bytes);
    // slike
    for (var im = 0; im < nImg; im++) {
      var img = this.images[im];
      writeObj(oFirstImg + im, '<< /Type /XObject /Subtype /Image /Width ' + img.w + ' /Height ' + img.h + ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' + img.bytes.length + ' >>', img.bytes);
    }
    // strani + vsebine
    var xobj = ''; for (var k = 0; k < nImg; k++) xobj += '/Im' + k + ' ' + (oFirstImg + k) + ' 0 R ';
    for (var pi = 0; pi < this.pages.length; pi++) {
      var contentNum = oFirstContent + pi, pageNum = oFirstPage + pi;
      var stream = this.pages[pi].ops.join('\n');
      var sb = bytesFromLatin1(stream);
      writeObj(pageNum, '<< /Type /Page /Parent ' + oPages + ' 0 R /MediaBox [0 0 ' + fmt(this.W) + ' ' + fmt(this.H) + '] /Resources << /Font << /F1 ' + oFont + ' 0 R >> /XObject << ' + xobj + '>> >> /Contents ' + contentNum + ' 0 R >>');
      writeObj(contentNum, '<< /Length ' + sb.length + ' >>', sb);
    }
    // xref
    var xrefPos = pos;
    var count = total + 1;
    var xref = 'xref\n0 ' + count + '\n0000000000 65535 f \n';
    for (var n = 1; n <= total; n++) { var o = offsets[n] || 0; xref += ('0000000000' + o).slice(-10) + ' 00000 n \n'; }
    push(xref);
    push('trailer\n<< /Size ' + count + ' /Root ' + oCatalog + ' 0 R >>\nstartxref\n' + xrefPos + '\n%%EOF');
    // združi
    var totalLen = 0; chunks.forEach(function (c) { totalLen += c.length; });
    var out = new Uint8Array(totalLen), p2 = 0;
    chunks.forEach(function (c) { out.set(c, p2); p2 += c.length; });
    return out;
  };
  PDFDoc.prototype.save = function (ime) {
    var bytes = this.build();
    var blob = new Blob([bytes], { type: 'application/pdf' });
    var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = ime;
    document.body.appendChild(a); a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 100);
  };
  // Pretvori data:image/png (ali katerokoli sliko) v JPEG bajte + dimenzije (Promise).
  PDFDoc.imageToJpeg = function (src, maxW) {
    return new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () {
        var scale = (maxW && img.width > maxW) ? maxW / img.width : 1;
        var w = Math.max(1, Math.round(img.width * scale)), h = Math.max(1, Math.round(img.height * scale));
        var cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        var ctx = cv.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, w, h); ctx.drawImage(img, 0, 0, w, h);
        try {
          var url = cv.toDataURL('image/jpeg', 0.92), b64 = url.split(',')[1];
          resolve({ bytes: b64ToBytes(b64), w: w, h: h });
        } catch (e) { reject(e); }
      };
      img.onerror = reject; img.src = src;
    });
  };
  window.PDFDoc = PDFDoc;
})();
